#include <SDL.h>
#include "render_device_api.hpp"
#include "indexed_geometry.hpp"
#include <vector>
#include <cstdio>
#include <cstdlib>
#include <cstring>
static void check(bool ok,const char*message){if(!ok){std::fprintf(stderr,"FAIL: %s\n",message);std::exit(1);}}
int main(){
 check(SDL_Init(SDL_INIT_VIDEO)==0,SDL_GetError());auto*w=SDL_CreateWindow("Indexed FFP fixture",0,0,64,64,SDL_WINDOW_HIDDEN|SDL_WINDOW_METAL);check(w,SDL_GetError());storm_render::Presentation pp{};pp.width=pp.height=64;pp.colorFormat=storm_render::AssetFormat::A8R8G8B8;storm_render::Device*d=nullptr;check(storm_render::succeeded(storm_render::createMetalDevice(w, &pp, &d)),"device");
 struct V{float x,y,z,rhw;uint32_t color;float u,v;};const V vertices[]={{8,8,.5f,1,0xffff2020,0,0},{56,8,.5f,1,0xff20ff20,1,0},{8,56,.5f,1,0xff2020ff,0,1},{56,56,.5f,1,0xffeeeeee,1,1}};
 d->SetFVF(storm_render::vertexFormat::xyzwTransformed|storm_render::vertexFormat::diffuse|storm_render::vertexFormat::tex1);d->SetRenderState(storm_render::RenderDepthTest,false);d->SetRenderState(storm_render::RenderCullMode,storm_render::CullNone);d->SetRenderState(storm_render::RenderLighting,false);d->SetRenderState(storm_render::RenderBlend,false);d->SetTextureStageState(0,storm_render::StageColorOp,storm_render::TextureOpModulate);d->SetTextureStageState(0,storm_render::StageColorArg1,storm_render::textureArg::texture);d->SetTextureStageState(0,storm_render::StageColorArg2,storm_render::textureArg::diffuse);d->SetTextureStageState(1,storm_render::StageColorOp,storm_render::TextureOpDisable);
 storm_render::Texture*texture=nullptr;d->CreateTexture(2, 2, 1, 0, storm_render::AssetFormat::A8R8G8B8, &texture);storm_render::LockedRect lock{};texture->LockRect(0,&lock,nullptr,0);const uint32_t texels[]={0xffffffff,0xff808080,0xffc0a080,0xff80a0c0};for(int y=0;y<2;y++)std::memcpy((char*)lock.pBits+y*lock.Pitch,texels+y*2,8);texture->UnlockRect(0);d->SetTexture(0,texture);
 storm_render::VertexBuffer*vb=nullptr;d->CreateVertexBuffer(sizeof(vertices)+16, 0, 0, &vb);void*data=nullptr;vb->Lock(0,0,&data,0);std::memset(data,0xee,16);std::memcpy((char*)data+16,vertices,sizeof(vertices));vb->Unlock();d->SetStreamSource(0,vb,16,sizeof(V));
 storm_render::Surface *target=nullptr,*readback=nullptr;d->GetRenderTarget(&target);d->CreateOffscreenPlainSurface(64, 64, storm_render::AssetFormat::A8R8G8B8, &readback);
 auto pixels=[&](){check(storm_render::succeeded(d->GetRenderTargetData(target,readback)),"readback");storm_render::LockedRect r{};readback->LockRect(&r,nullptr,storm_render::lock::readOnly);std::vector<uint32_t> result(64*64);for(int y=0;y<64;y++)std::memcpy(result.data()+y*64,(char*)r.pBits+y*r.Pitch,64*4);readback->UnlockRect();return result;};
 struct Case{storm_render::Primitive type;uint32_t primitives;std::vector<uint32_t> indices;};
 const Case cases[]={{storm_render::PrimitiveTriangleList,2,{0,1,2,2,1,3}},{storm_render::PrimitiveTriangleStrip,4,{0,1,2,3,2,1}},{storm_render::PrimitiveTriangleFan,2,{0,1,3,2}},{storm_render::PrimitiveLineList,4,{0,1,1,3,3,2,2,0}},{storm_render::PrimitiveLineStrip,5,{0,1,3,2,0,1}},{storm_render::PrimitiveTriangleList,1,{0,1,3}}};
 for(auto&c:cases){
  std::vector<V> expanded;for(auto index:c.indices)expanded.push_back(vertices[index]);d->Clear(storm_render::clear::color, 0xff102030, 1);d->BeginScene();check(storm_render::succeeded(d->DrawPrimitiveUP(c.type,c.primitives,expanded.data(),sizeof(V))),"expanded reference");d->EndScene();auto reference=pixels();
  for(bool wide:{false,true}){size_t width=wide?4:2;std::vector<uint8_t> indexBytes((c.indices.size()+1)*width);for(size_t i=0;i<c.indices.size();i++){uint32_t value=c.indices[i]+2;if(wide)std::memcpy(indexBytes.data()+(i+1)*width,&value,4);else{uint16_t small=uint16_t(value);std::memcpy(indexBytes.data()+(i+1)*width,&small,2);}}
   storm_render::IndexBuffer*ib=nullptr;d->CreateIndexBuffer(uint32_t(indexBytes.size()), 0, wide?storm_render::IndexFormat::UInt32:storm_render::IndexFormat::UInt16, &ib);ib->Lock(0,0,&data,0);std::memcpy(data,indexBytes.data(),indexBytes.size());ib->Unlock();d->SetIndices(ib);d->SetStreamSource(0,vb,16,sizeof(V));d->Clear(storm_render::clear::color, 0xff102030, 1);d->BeginScene();check(storm_render::succeeded(d->DrawIndexedPrimitive(c.type,-2,2,4,1,c.primitives)),"signed base and nonzero min/start/stream offset");d->EndScene();check(pixels()==reference,"indexed topology/colors/UV match expanded");
   check(storm_render::failed(d->DrawIndexedPrimitive(c.type,-3,2,4,1,c.primitives)),"negative physical vertex rejected");check(storm_render::failed(d->DrawIndexedPrimitive(c.type,-2,3,3,1,c.primitives)),"index below declared min rejected");check(storm_render::failed(d->DrawIndexedPrimitive(c.type,-2,2,3,1,c.primitives)),"index above declared range rejected");check(storm_render::failed(d->DrawIndexedPrimitive(c.type,-2,2,5,1,c.primitives)),"declared VB overrun rejected");check(storm_render::failed(d->DrawIndexedPrimitive(c.type,-2,2,4,2,c.primitives)),"IB overrun rejected");check(storm_render::failed(d->DrawIndexedPrimitive(c.type,-2,2,4,UINT32_MAX,c.primitives)),"index offset overflow rejected");d->SetIndices(nullptr);ib->Release();
  }
  d->Clear(storm_render::clear::color, 0xff102030, 1);d->BeginScene();check(storm_render::succeeded(d->DrawIndexedPrimitiveUP(c.type,0,4,c.primitives,c.indices.data(),storm_render::IndexFormat::UInt32,vertices,sizeof(V))),"indexed UP");d->EndScene();check(pixels()==reference,"indexed UP matches expanded");
 }
 sm::IndexedSpan span;const uint16_t repeated[]={2,3,4,4,3,5};check(sm::indexedSpan(repeated,false,6,-2,2,4,4,span)&&span.vertices()==4,"six references convert four vertices");check(!sm::indexedSpan(repeated,false,6,INT32_MIN,2,4,4,span),"signed base extreme rejected");check(!sm::indexedSpan(repeated,false,6,0,UINT32_MAX,4,4,span),"declared range overflow rejected");
 std::puts("PASS: 16/32-bit indexed list/strip/fan/lines match expanded colors+UV; signed base/min/start/offset; invalid VB/IB/ranges; 6 references -> 4 conversions");target->Release();readback->Release();texture->Release();vb->Release();d->Release();SDL_DestroyWindow(w);SDL_Quit();
}
